import re

def run(data: dict) -> dict:
    csv = data.get("csv")
    required_headers = data.get("required_headers", [])

    if not csv:
        return {
            "missing_headers": required_headers,
            "found_headers": [],
            "is_valid": False
        }

    lines = csv.splitlines()
    if len(lines) < 2:
        return {
            "missing_headers": required_headers,
            "found_headers": [],
            "is_valid": False
        }

    header = lines[0].strip()
    found_headers = header.split(',')
    missing_headers = [header for header in required_headers if header not in found_headers]

    is_valid = len(missing_headers) == 0

    return {
        "missing_headers": missing_headers,
        "found_headers": found_headers,
        "is_valid": is_valid
    }

