import unittest
from main import run

class TestValidateCSVHeader(unittest.TestCase):
    def test_valid_csv(self):
        input_data = {
            "csv": "name,age,city\nJohn,30,New York",
            "required_headers": ["name", "age", "city"]
        }
        expected_output = {
            "missing_headers": [],
            "found_headers": ["name", "age", "city"],
            "is_valid": True
        }
        self.assertEqual(run(input_data), expected_output)

    def test_missing_required_header(self):
        input_data = {
            "csv": "name,city\nJohn,New York",
            "required_headers": ["name", "age", "city"]
        }
        expected_output = {
            "missing_headers": ["age"],
            "found_headers": ["name", "city"],
            "is_valid": False
        }
        self.assertEqual(run(input_data), expected_output)

    def test_empty_csv(self):
        input_data = {
            "csv": "",
            "required_headers": ["name", "age", "city"]
        }
        expected_output = {
            "missing_headers": ["name", "age", "city"],
            "found_headers": [],
            "is_valid": False
        }
        self.assertEqual(run(input_data), expected_output)

    def test_no_header_row(self):
        input_data = {
            "csv": "John,30,New York",
            "required_headers": ["name", "age", "city"]
        }
        expected_output = {
            "missing_headers": ["name", "age", "city"],
